```ts
// queue.ts
export class JobQueue {
  private running = 0;
  private pending: (() => Promise<void>)[] = [];
  private idleWaiters: (() => void)[] = [];
  private concurrency: number;
  private maxRetries: number;

  constructor(concurrency: number, maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries run out. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.attempt(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async attempt<T>(job: () => Promise<T>): Promise<T> {
    // ponytail: retries immediately, add backoff if jobs hit a rate-limited or recovering service
    for (let retries = 0; ; retries++) {
      try {
        return await job();
      } catch (err) {
        if (retries >= this.maxRetries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      this.running++;
      this.pending.shift()!().finally(() => {
        this.running--;
        this.next();
      });
    }
    if (this.running === 0 && this.pending.length === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}
