// queue.demo.ts — run with: npx tsx queue.demo.ts
import assert from "node:assert/strict";
import { JobQueue } from "./queue.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const q = new JobQueue(2);

let active = 0, peak = 0;
const results = Array.from({ length: 6 }, (_, i) =>
  q.add(async () => {
    peak = Math.max(peak, ++active);
    await sleep(10);
    active--;
    return i;
  }),
);

let flakyCalls = 0;
const flaky = q.add(async () => {
  if (++flakyCalls < 4) throw new Error("flaky");
  return "ok";
});

let failingCalls = 0;
const failing = q
  .add(async () => { failingCalls++; throw new Error("always"); })
  .catch((e: Error) => e.message);

await q.onIdle();
assert.equal(peak, 2);
assert.deepEqual(await Promise.all(results), [0, 1, 2, 3, 4, 5]);
assert.equal(await flaky, "ok"); // succeeds on the fourth attempt
assert.equal(await failing, "always");
assert.equal(failingCalls, 4); // 1 try + 3 retries
console.log("ok");
```

`onIdle()` never rejects. A job's failure surfaces only on the promise returned by `add()`, so a fire-and-forget `add()` whose job fails for good becomes an unhandled rejection, which crashes Node by default. Attach a `.catch` to each `add()` you don't await.

