```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* environment variables
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, String(row.id)])).toString('base64url');

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString());
    if (typeof ts === 'string' && typeof id === 'string') return [ts, id];
  } catch {}
  return null;
}

router.get('/orders', async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer from 1 to ${MAX_LIMIT}` });
  }

  let after = [];
  if (req.query.cursor !== undefined) {
    after = typeof req.query.cursor === 'string' && decodeCursor(req.query.cursor);
    if (!after) return res.status(400).json({ error: 'invalid cursor' });
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms and skip or repeat rows.
    const { rows } = await pool.query(
      `SELECT id, customer_id, status, total_cents, created_at, created_at::text AS cursor_ts
         FROM orders
        ${after.length ? 'WHERE (created_at, id) < ($2::timestamptz, $3::bigint)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...after], // one extra row tells us whether there is a next page
    );

    const page = rows.slice(0, limit);
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // Class 22 = data exception: a well-formed cursor carrying a bad timestamp or id.
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;
```

The query needs a matching index to stay fast on deep pages:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

The client calls `GET /orders?limit=20`, then passes `next_cursor` back as `?cursor=...` until it comes back `null`.

- **Authorisation is missing:** as written, the route lists every customer's orders. Add `customer_id = <authenticated user>` to the `WHERE` clause and put `customer_id` first in the index, unless this is an admin-only endpoint.
- **Non-bigint ids:** if `id` is a UUID, change the `$3::bigint` cast to `$3::uuid`.

Skipped: a previous-page cursor and a total count. Add them when the UI needs them; a total count needs a separate `COUNT(*)` query, which gets slow on large tables.

