`AbortSignal.timeout` is built into modern browsers and Node 18+. If the timeout fires, the promise rejects with a `TimeoutError`:

```js
try {
  const res = await fetch(url, { signal: AbortSignal.timeout(5000) });
} catch (err) {
  if (err.name === "TimeoutError") {
    // took longer than 5 seconds
  } else {
    throw err;
  }
}
```

The timeout also covers reading the body, so a slow `await res.json()` after the headers arrive is aborted by the same 5 seconds.

```js
function throttle(fn, ms) {
  let last = 0;
  let timer;
  return (...args) => {
    const wait = last + ms - Date.now();
    clearTimeout(timer);
    if (wait <= 0) {
      last = Date.now();
      fn(...args);
    } else {
      // trailing call, so the final scroll position is not missed
      timer = setTimeout(() => {
        last = Date.now();
        fn(...args);
      }, wait);
    }
  };
}

window.addEventListener("scroll", throttle(onScroll, 200), { passive: true });
